import type { CreateHost, Host, Message, NodeView, Outcome } from '../host.ts';

const NODE_IDS = ['n0', 'n1', 'n2'] as const;
const MAJORITY = 2;

interface NodeState {
  role: NodeView['role'];
  term: number;
  votedFor: string | null;
  votes: Set<string>;
}

const createHost: CreateHost = async () => {
  const nodes = new Map<string, NodeState>();
  for (const id of NODE_IDS) {
    nodes.set(id, { role: 'follower', term: 0, votedFor: null, votes: new Set() });
  }
  const inFlight = new Map<string, Message>();
  let nextId = 1;

  function send(from: string, to: string, action: string, data: Record<string, unknown>): void {
    const id = `m${nextId++}`;
    inFlight.set(id, { id, from, to, action, data });
  }

  function onRequestVote(self: string, msg: Message): void {
    const node = nodes.get(self)!;
    const candidate = msg.data.from;
    const term = msg.data.term;
    if (typeof candidate !== 'string' || term !== 1) return;
    let granted = false;
    if (node.term === 0) {
      node.term = 1;
      node.role = 'follower';
      node.votedFor = candidate;
      granted = true;
    } else if (node.term === 1) {
      if (node.role === 'follower' && (node.votedFor === null || node.votedFor === candidate)) {
        node.votedFor = candidate;
        granted = true;
      }
    }
    send(self, candidate, 'VoteReply', { term: 1, granted });
  }

  function onVoteReply(self: string, msg: Message): void {
    const node = nodes.get(self)!;
    if (node.role !== 'candidate' || msg.data.term !== node.term || msg.data.granted !== true) return;
    node.votes.add(msg.from);
    if (node.votes.size >= MAJORITY) node.role = 'leader';
  }

  async function deliver(id: string): Promise<void> {
    const msg = inFlight.get(id);
    if (!msg) return;
    inFlight.delete(id);
    if (!nodes.has(msg.to)) return;
    if (msg.action === 'RequestVote') onRequestVote(msg.to, msg);
    else if (msg.action === 'VoteReply') onVoteReply(msg.to, msg);
  }

  const host: Host = {
    async inFlight() {
      return [...inFlight.values()].map((m) => ({ ...m, data: { ...m.data } }));
    },
    deliver,
    async deliverAll() {
      while (inFlight.size > 0) {
        const [id] = inFlight.keys();
        await deliver(id);
      }
    },
    async timeout(id: string): Promise<Outcome> {
      const node = nodes.get(id);
      if (!node) return { ok: false, reason: `unknown node: ${id}` };
      if (node.role !== 'follower' || node.term !== 0) {
        return { ok: false, reason: `${id} cannot start an election: it is a ${node.role} in term ${node.term}` };
      }
      node.role = 'candidate';
      node.term = 1;
      node.votedFor = id;
      node.votes = new Set([id]);
      for (const peer of NODE_IDS) {
        if (peer !== id) send(id, peer, 'RequestVote', { from: id, term: 1 });
      }
      return { ok: true };
    },
    async node(id: string): Promise<NodeView | null> {
      const node = nodes.get(id);
      if (!node) return null;
      return { role: node.role, term: node.term, votedFor: node.votedFor };
    },
  };
  return host;
};

export default createHost;
EOF
cat > test/host.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('single candidate wins', async () => {
  const h = await createHost();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 0, votedFor: null });
  assert.equal(await h.node('x'), null);
  assert.equal((await h.timeout('x')).ok, false);
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.equal((await h.timeout('n0')).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs[0].data, { from: 'n0', term: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

test('random orders: safety', async () => {
  let seed = 7;
  const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);
  for (let i = 0; i < 2000; i++) {
    const h = await createHost();
    const starters = ['n0', 'n1', 'n2'].filter(() => rnd() < 0.7);
    for (const s of starters) await h.timeout(s);
    for (;;) {
      const f = await h.inFlight();
      if (rnd() < 0.2) { const s = ['n0', 'n1', 'n2'][Math.floor(rnd() * 3)]; await h.timeout(s); }
      if (!f.length) break;
      await h.deliver(f[Math.floor(rnd() * f.length)].id);
    }
    const views = await Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));
    const leaders = ['n0', 'n1', 'n2'].filter((_, k) => views[k]!.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const l of leaders) assert.ok(views.filter((v) => v!.votedFor === l).length >= 2);
  }
});
EOF
