    if (typeof leader !== 'string' || msg.data.term !== 1 || node.role === 'leader') return;
    if (node.term === 0) node.term = 1;
    node.role = 'follower';
    node.leader = leader;
  }

  async function deliver(id: string): Promise<void> {
    const msg = inFlight.get(id);
    if (!msg) return;
    inFlight.delete(id);
    if (!nodes.has(msg.to)) return;
