import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('single candidate wins and announces', async () => {
  const h = await createHost();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('x'), null);
  assert.equal((await h.timeout('x')).ok, false);
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.equal((await h.timeout('n0')).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs[0].data, { from: 'n0', term: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

test('Leader reaches a term-0 node before RequestVote; candidate steps down', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n2');
  const rv = (await h.inFlight()).find((m) => m.from === 'n0' && m.to === 'n1')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  await h.deliver(reply.id);
  assert.equal((await h.node('n0'))!.role, 'leader');
  const ann = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.deepEqual(ann.map((m) => m.to).sort(), ['n1', 'n2']);
  assert.deepEqual(ann[0].data, { from: 'n0', term: 1 });
  for (const m of ann) await h.deliver(m.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
  assert.equal((await h.node('n0'))!.role, 'leader');
});

test('term-0 node learns leader without voting', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const toN1 = (await h.inFlight()).find((m) => m.to === 'n1')!;
  await h.deliver(toN1.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  const ann = (await h.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!;
  await h.deliver(ann.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
});

test('random orders: safety', async () => {
  let seed = 7;
  const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
  const ids = ['n0', 'n1', 'n2'];
  for (let i = 0; i < 2000; i++) {
    const h = await createHost();
    for (const s of ids) if (rnd() < 0.7) await h.timeout(s);
    for (;;) {
      if (rnd() < 0.2) await h.timeout(ids[Math.floor(rnd() * 3)]);
      const f = await h.inFlight();
      if (!f.length) break;
      await h.deliver(f[Math.floor(rnd() * f.length)].id);
    }
    const views = await Promise.all(ids.map((n) => h.node(n)));
    const leaders = ids.filter((_, k) => views[k]!.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const l of leaders) {
      assert.ok(views.filter((v) => v!.votedFor === l).length >= 2);
      for (const v of views) assert.equal(v!.leader, l);
    }
  }
});

