  let seed = 7;
  const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
  const ids = ['n0', 'n1', 'n2'];
  for (let i = 0; i < 2000; i++) {
    const h = await createHost();
    for (const s of ids) if (rnd() < 0.7) await h.timeout(s);
    for (;;) {
      if (rnd() < 0.2) await h.timeout(ids[Math.floor(rnd() * 3)]);
      if (rnd() < 0.1) await h.giveUp(ids[Math.floor(rnd() * 3)]);
      const f = await h.inFlight();
      if (!f.length) break;
      await h.deliver(f[Math.floor(rnd() * f.length)].id);
    }
    const views = await Promise.all(ids.map((n) => h.node(n)));
    const leaders = ids.filter((_, k) => views[k]!.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const l of leaders) {
      assert.ok(views.filter((v) => v!.votedFor === l).length >= 2);
      for (const v of views) assert.equal(v!.leader, l);
    }
  }
});

