  await h.deliver(ann.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
});

test('giveUp', async () => {
  const h = await createHost();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('zz')).ok, false);
  await h.timeout('n0');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.timeout('n1');
  for (const m of await h.inFlight()) if (m.from === 'n1') await h.deliver(m.id);
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n1' });
  assert.deepEqual(await h.node('n1'), { role: 'leader', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.equal((await h.giveUp('n1')).ok, false);
});

test('crash and recover', async () => {
  const h = await createHost();
  assert.equal((await h.recover('n0')).ok, false);
  assert.equal((await h.crash('zz')).ok, false);
  assert.deepEqual(await h.crash('n2'), { ok: true });
  assert.equal((await h.crash('n2')).ok, false);
  assert.equal((await h.timeout('n2')).ok, false);
  assert.equal((await h.giveUp('n2')).ok, false);
  assert.deepEqual(await h.node('n2'), { role: 'down', term: 0, votedFor: null, leader: null });
  await h.timeout('n0');
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n2'), { role: 'down', term: 0, votedFor: null, leader: null });
  assert.deepEqual(await h.recover('n2'), { ok: true });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 0, votedFor: null, leader: null });
  await h.crash('n0');
  assert.deepEqual(await h.node('n0'), { role: 'down', term: 1, votedFor: 'n0', leader: 'n0' });
  await h.recover('n0');
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  // n2 may still start an election but cannot win: both others voted for n0.
  assert.deepEqual(await h.timeout('n2'), { ok: true });
  await h.deliverAll();
  assert.equal((await h.node('n2'))!.role, 'candidate');
});

test('crashed candidate ignores late replies after recovery', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.crash('n0');
  for (const m of await h.inFlight()) await h.deliver(m.id);
  await h.recover('n0');
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.timeout('n0')).ok, false);
});

test('random orders: safety', async () => {
  let seed = 7;
  const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
  const ids = ['n0', 'n1', 'n2'];
  for (let i = 0; i < 2000; i++) {
    const h = await createHost();
    for (const s of ids) if (rnd() < 0.7) await h.timeout(s);
    for (;;) {
      if (rnd() < 0.2) await h.timeout(ids[Math.floor(rnd() * 3)]);
      if (rnd() < 0.1) await h.giveUp(ids[Math.floor(rnd() * 3)]);
      if (rnd() < 0.1) await h.crash(ids[Math.floor(rnd() * 3)]);
      if (rnd() < 0.1) await h.recover(ids[Math.floor(rnd() * 3)]);
      const vs = await Promise.all(ids.map((n) => h.node(n)));
      assert.ok(vs.filter((v) => v!.role === 'leader').length <= 1);
      const f = await h.inFlight();
      if (!f.length) break;
      await h.deliver(f[Math.floor(rnd() * f.length)].id);
    }
    const views = await Promise.all(ids.map((n) => h.node(n)));
    const leaders = ids.filter((_, k) => views[k]!.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const l of leaders) {
      assert.ok(views.filter((v) => v!.votedFor === l).length >= 2);
      for (const v of views) assert.equal(v!.leader, l);
    }
  }
});
